#!/usr/bin/env python3
"""Series125: multi-hop structural specificity audit of the frozen61x61 graph.

Targets are generated by the same frozen graph, so this is a structural self-consistency
benchmark, not independent behavioral or biological validation.
"""
from __future__ import annotations
import argparse,csv,hashlib,json,os,threading,time,traceback,uuid
from datetime import datetime
from pathlib import Path
import numpy as np
HERE=Path(__file__).resolve().parent; REPORTS=HERE.parent/'reports'; MATRIX=REPORTS/'biological-digital-pipeline-116a-61x61.csv'; PATHS=REPORTS/'biological-digital-pipeline-116b-61x8.csv'; PROTOS=REPORTS/'adaptive-three-direction-118-action-prototypes.json'
MATRIX_SHA='03157b503d0271cb0991db524d45220bb8f49ce62e3ba171dc997ed7f3816150';PATHS_SHA='4186bb6fdbe0a0e81f8626469027976ade1d416ff0549af94b85fb1b07aa3ca1';PROTOS_SHA='28edd80b81111d47708f163aaf9b250f7ad330a87d6c9dc5ee70e7895843ca04';OUTPUT_ROOT=Path('workspace/runs/ideas/i-observational/multihop-structural-125');FINAL_SEED=125_000_003;HOPS=4;GAMMA=.65

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def load():
    if (sha(MATRIX),sha(PATHS),sha(PROTOS))!=(MATRIX_SHA,PATHS_SHA,PROTOS_SHA):raise ValueError('Frozen input SHA mismatch.')
    mr=list(csv.reader(MATRIX.open(encoding='utf8')));pr=list(csv.reader(PATHS.open(encoding='utf8')));p=np.asarray(json.loads(PROTOS.read_text(encoding='utf8'))['prototypes'])
    g=np.asarray([[float(x) for x in r[1:]] for r in mr[1:]]);g=np.log1p(g);g/=np.maximum(g.sum(1,keepdims=True),1e-15);paths=np.asarray([[float(x) for x in r[1:]] for r in pr[1:]]);paths/=np.maximum(paths.sum(1,keepdims=True),1e-15);return g,paths,p
G,PATH,P=load()
def stimuli(count,seed):
    rng=np.random.default_rng(seed);out=[]
    for i in range(count):
        weights=rng.dirichlet(np.ones(3));x=weights@P
        if i%3==0:
            idx=rng.choice(61,int(rng.integers(2,9)),replace=False);imp=np.zeros(61);imp[idx]=rng.uniform(.2,1,len(idx));imp/=imp.sum();x=.65*x+.35*imp
        x=np.clip(x+rng.normal(0,.002,61),0,None);x/=max(x.sum(),1e-15);out.append(x)
    return np.asarray(out)
def propagate(matrix,x,hops=HOPS,gamma=GAMMA):
    z=x.copy();total=x.copy()
    for h in range(1,hops+1):z=z@matrix;total+=gamma**h*z
    return total/np.maximum(total.sum(1,keepdims=True),1e-15)
def controls():
    rng=np.random.default_rng(125_000_001);nz=G>0
    shuffled=G.copy();values=shuffled[nz].copy();rng.shuffle(values);shuffled[nz]=values;shuffled/=np.maximum(shuffled.sum(1,keepdims=True),1e-15)
    rewired=np.zeros_like(G)
    for i in range(61):
        vals=G[i,G[i]>0];targets=rng.choice(61,len(vals),replace=False);rewired[i,targets]=vals
    rewired/=np.maximum(rewired.sum(1,keepdims=True),1e-15)
    perm=rng.permutation(61);permuted=G[perm][:,perm]
    u,s,vt=np.linalg.svd(G,full_matrices=False);low=(u[:,:8]*s[:8])@vt[:8];low=np.clip(low,0,None);low/=np.maximum(low.sum(1,keepdims=True),1e-15)
    random=np.zeros_like(G);random[nz]=rng.uniform(.01,1,np.count_nonzero(nz));random/=np.maximum(random.sum(1,keepdims=True),1e-15)
    return {'full_multihop':G,'one_hop':G,'identity':np.eye(61),'weight_shuffled':shuffled,'topology_rewired':rewired,'node_labels_permuted':permuted,'rank8_approximation':low,'matched_random_weights':random}
def metric(pred,target):
    dn_pred=pred@PATH;dn_target=target@PATH;cos=np.sum(pred*target,1)/(np.linalg.norm(pred,axis=1)*np.linalg.norm(target,axis=1)+1e-15)
    return {'type_rmse':float(np.sqrt(np.mean((pred-target)**2))),'type_cosine':float(np.mean(cos)),'dn_rmse':float(np.sqrt(np.mean((dn_pred-dn_target)**2))),'dn_top1_accuracy':float(np.mean(np.argmax(dn_pred,1)==np.argmax(dn_target,1)))}
def run(case_count,output_root,progress=lambda *_:None):
    folder=output_root/('multihop_structural_125_'+datetime.now().strftime('%Y%m%d_%H%M%S')+'_'+uuid.uuid4().hex[:8]);folder.mkdir(parents=True);x=stimuli(case_count,FINAL_SEED);target=propagate(G,x);rows=[];progress(1,3,'Controls')
    for name,m in controls().items():
        start=time.perf_counter();pred=propagate(m,x,1 if name=='one_hop' else (0 if name=='identity' else HOPS));elapsed=time.perf_counter()-start;rows.append({'name':name,**metric(pred,target),'mean_seconds_per_case':elapsed/case_count})
    lesions=[];rng=np.random.default_rng(125_000_002)
    for fraction in [.10,.25,.50]:
        les=G.copy();idx=np.argwhere(les>0);drop=rng.choice(len(idx),int(len(idx)*fraction),replace=False);les[idx[drop,0],idx[drop,1]]=0;les/=np.maximum(les.sum(1,keepdims=True),1e-15);lesions.append({'edge_dropout':fraction,**metric(propagate(les,x),target)})
    by={r['name']:r for r in rows};passed=by['full_multihop']['type_rmse']<1e-12 and by['one_hop']['type_rmse']>1e-4 and all(by[n]['type_rmse']>1e-4 for n in ['topology_rewired','node_labels_permuted','matched_random_weights'])
    result={'schema':'multihop-structural-specificity-125-v1','status':'completed','contract':{'case_count':case_count,'final_seed':FINAL_SEED,'hops':HOPS,'gamma':GAMMA,'targets_generated_by_same_frozen_graph':True,'structural_self_consistency_only':True,'independent_behavior_target':False,'frozen_input_shas':{'matrix':MATRIX_SHA,'paths':PATHS_SHA,'prototypes':PROTOS_SHA},'not_biological_validation':True,'not_physical_flygym_run':True},'models':rows,'edge_lesions':lesions,'gates':{'structural_specificity_pass':passed,'external_behavior_advantage_claim':False,'new_physical_port_authorized':False},'interpretation':{'full_graph_zero_error_is_true_by_construction':True,'control_failures_show_nonredundant_multihop_topology_for_its_own_defined_operator':True,'does_not_show_real_world_utility':True}}
    (folder/'summary.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf8');lines=['SERIES125 — MULTIHOP STRUCTURAL SPECIFICITY','',f'Cases: {case_count} | hops: {HOPS} | gamma: {GAMMA}',f"Structural specificity: {passed}",'']+[f"{r['name']}: type RMSE={r['type_rmse']:.8f}, DN RMSE={r['dn_rmse']:.8f}, DN top1={r['dn_top1_accuracy']*100:.2f}%" for r in rows]+['','Self-consistency only: target is generated by the same frozen graph.'];(folder/'ИТОГ.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8-sig');progress(3,3,'Готово');return folder
def gui():
    import tkinter as tk
    from tkinter import messagebox,ttk
    root=tk.Tk();root.title('Series125: multihop structural specificity');root.geometry('760x390+90+60');root.attributes('-topmost',True);cases=tk.IntVar(value=600);status=tk.StringVar(value='Готово');bar=tk.DoubleVar(value=0)
    tk.Label(root,text='61×61 multi-hop structural specificity',font=('Arial',15,'bold'),pady=15).pack();tk.Label(root,text='Full graph · one-hop · rewired · shuffled · permuted · low-rank · lesions\nSelf-consistency, not independent behavior or biology.',justify='center').pack();form=tk.Frame(root);form.pack(pady=16);tk.Label(form,text='Final cases:').grid(row=0,column=0,padx=6);tk.Spinbox(form,from_=60,to=5000,increment=60,textvariable=cases,width=9).grid(row=0,column=1);tk.Label(root,textvariable=status).pack();ttk.Progressbar(root,variable=bar,maximum=3,length=560).pack(pady=8);button=tk.Button(root,text='Запустить Series125',padx=20,pady=9);button.pack(pady=10)
    def start():
        button.config(state='disabled');n=int(cases.get())
        def work():
            try:
                out=run(n,OUTPUT_ROOT,lambda d,t,s:root.after(0,lambda:(bar.set(d),status.set(s))))
                def done():
                    button.config(state='normal');status.set('Готово');
                    if os.name=='nt':os.startfile(str(out.resolve()))
                    messagebox.showinfo('Series125',f'Результат:\n{out.resolve()}',parent=root)
                root.after(0,done)
            except Exception as e:
                p=OUTPUT_ROOT/'ПОСЛЕДНЯЯ-ОШИБКА-125.txt';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(type(e).__name__+': '+str(e)+'\n\n'+traceback.format_exc(),encoding='utf-8-sig');root.after(0,lambda:(button.config(state='normal'),status.set('Ошибка'),messagebox.showerror('Series125',f'{e}\n\n{p.resolve()}',parent=root)))
        threading.Thread(target=work,daemon=True).start()
    button.config(command=start);root.mainloop()
def main():
    p=argparse.ArgumentParser();p.add_argument('--gui',action='store_true');p.add_argument('--cases',type=int,default=600);p.add_argument('--output-root',type=Path,default=OUTPUT_ROOT);a=p.parse_args();print(run(a.cases,a.output_root)) if not a.gui else gui()
if __name__=='__main__':main()
